import { useState, useEffect, useCallback } from 'react'
import { StyleContainer, Content } from './index.styles'
import GuideSection from './GuideSection'
import UploadArea from './UploadArea'
import ErrorModal from './ErrorModal'
import { UPLOAD_STATUS, ERROR_TYPE, ACCEPTED_FILE_TYPES } from './constants'
import { downloadFile } from '../../../../../../helpers/mitraUtils/mitra-utility'
import ShowSnackbar from '../../../../../../components/ShowNotification'
import { useBulkUploadApi } from './hooks/useBulkUploadApi'
import { replaceUrlTemplate } from './helpers'

const BulkUploadExcel = ({ fieldConfig, draftData, onChange }) => {
  const { params, key } = fieldConfig
  const { text_instruction, template_file } = params

  const [status, setStatus] = useState(UPLOAD_STATUS.IDLE)
  const [file, setFile] = useState(null)
  const [errorModalVisible, setErrorModalVisible] = useState(false)
  const [errorType, setErrorType] = useState(null)
  const [loadingDownloadTemplate, setLoadingDownloadTemplate] = useState(false)

  const {
    loading,
    errorMessage,
    handleUploadBulkExcel,
    isErrorPartial,
    errorPartialCount,
    isError,
    isSuccess,
    handleDownloadErrorData,
    handleResetError,
  } = useBulkUploadApi()

  const checkIsValidExcelFile = useCallback(
    (file) => ACCEPTED_FILE_TYPES.some((extension) => file.name.endsWith(extension)),
    []
  )

  const handleFileSelect = useCallback(
    (selectedFile) => {
      if (!checkIsValidExcelFile(selectedFile)) {
        setErrorType(ERROR_TYPE.FULL)
        setErrorModalVisible(true)
        ShowSnackbar.error({
          text: 'Format file tidak valid. Silakan upload file dengan format .xlsx atau .xls',
        })
        return
      }

      setFile(selectedFile)
      const formData = new FormData()
      formData.append('file', selectedFile)

      // Get draftId from draftData
      const draftId = draftData?.draft_id
      if (!draftId) {
        ShowSnackbar.error({ text: 'Draft ID not found' })
        return
      }

      // Get upload endpoint from params and replace template placeholders
      let uploadEndpoint = params?.upload_url
      if (uploadEndpoint) {
        try {
          uploadEndpoint = replaceUrlTemplate(uploadEndpoint, draftData)
        } catch (error) {
          ShowSnackbar.error({ text: error?.message ?? 'Failed to process upload URL' })
          return
        }
      }

      handleUploadBulkExcel({ draftId, uploadEndpoint, body: formData })
    },
    [checkIsValidExcelFile, draftData, params, handleUploadBulkExcel]
  )

  const handleDrop = useCallback(
    (e) => {
      e.preventDefault()
      e.dataTransfer.files[0] && handleFileSelect(e.dataTransfer.files[0])
    },
    [handleFileSelect]
  )

  const handleDragOver = useCallback((e) => e.preventDefault(), [])

  const handleDownloadTemplate = useCallback(() => {
    setLoadingDownloadTemplate(true)
    try {
      if (template_file) {
        const fileName = template_file.split('/').pop()
        downloadFile(template_file, fileName)
      } else {
        ShowSnackbar.error({ text: 'Template file not found' })
      }
    } catch (error) {
      ShowSnackbar.error({ text: error?.message ?? 'Unknown error occurred' })
    } finally {
      setLoadingDownloadTemplate(false)
    }
  }, [template_file])

  const handleUploadAgain = useCallback(() => {
    setStatus(UPLOAD_STATUS.IDLE)
    setFile(null)
    setErrorModalVisible(false)
    handleResetError()
  }, [handleResetError])

  const handleDownloadError = useCallback(() => {
    handleDownloadErrorData()
  }, [handleDownloadErrorData])

  // Handle upload state and response
  useEffect(() => {
    if (loading) {
      setStatus(UPLOAD_STATUS.LOADING)
    } else if (isSuccess) {
      setStatus((prev) => {
        if (prev === UPLOAD_STATUS.SUCCESS) return prev
        ShowSnackbar.success({ text: 'Upload berhasil' })
        onChange?.({ [key]: { fileName: file?.name, uploaded: true } })
        return UPLOAD_STATUS.SUCCESS
      })
    } else if (isError) {
      if (isErrorPartial) {
        setStatus(UPLOAD_STATUS.ERROR_PARTIAL)
        setErrorType(ERROR_TYPE.PARTIAL)
        setErrorModalVisible(true)
      } else {
        setStatus(UPLOAD_STATUS.ERROR_FULL)
        setErrorType(ERROR_TYPE.FULL)
        setErrorModalVisible(true)
        ShowSnackbar.error({ text: errorMessage })
      }
    } else {
      setStatus(UPLOAD_STATUS.IDLE)
    }
  }, [loading, isSuccess, isError, isErrorPartial, errorMessage, key, file, onChange])

  // Reset error data
  useEffect(() => {
    if (!errorModalVisible) {
      setErrorType(null)
      handleResetError()
    }
  }, [errorModalVisible, handleResetError])

  return (
    <StyleContainer>
      <Content>
        <GuideSection
          handleDownloadTemplate={handleDownloadTemplate}
          loading={loadingDownloadTemplate}
          instruction={text_instruction}
        />
        <UploadArea
          status={status}
          file={file}
          handleFileSelect={handleFileSelect}
          handleUploadAgain={handleUploadAgain}
          handleDrop={handleDrop}
          handleDragOver={handleDragOver}
        />
      </Content>
      <ErrorModal
        errorModalVisible={errorModalVisible}
        errorType={errorType}
        setErrorModalVisible={setErrorModalVisible}
        handleUploadAgain={handleUploadAgain}
        handleDownloadError={handleDownloadError}
        errorMessage={errorMessage}
        isErrorPartial={isErrorPartial}
        errorPartialCount={errorPartialCount}
      />
    </StyleContainer>
  )
}

export default BulkUploadExcel
