import { formatMoney, formatNumber } from '../../../../../../helpers/utility'
import { CardContainer, TopSection, BottomSection } from './index.style'

function BasicPackageCardV1({ variant, packageData, onClick }) {
  const handleClick = () => {
    if (onClick) onClick(packageData)
  }

  return (
    <CardContainer variant={variant} onClick={handleClick}>
      <TopSection>
        <img className="logo" src={packageData?.logo_url} alt="" />
        <div className="provider">{packageData?.provider?.name}</div>
        <div className="package">{packageData?.package?.name}</div>
      </TopSection>
      <hr />
      <BottomSection>
        <div>
          <div>Premi Dasar</div>
          <div>{formatMoney(packageData?.premium_breakup?.total_premium?.premium, 0)}</div>
        </div>
        <div>
          <div>Total Komisi ({packageData?.commission_rate}%)</div>
          <div>{formatMoney(packageData?.commission, 0)}</div>
        </div>
        <div>
          <div>Total Poin</div>
          <div>{formatNumber(packageData?.points, { suffix: 'P' })}</div>
        </div>
      </BottomSection>
    </CardContainer>
  )
}

export default BasicPackageCardV1
