import _ from 'lodash'
import { useEffect, useMemo } from 'react'
import { useLocation } from 'react-router'
import { PACKAGE_DETAIL_API } from '../../constants'
import { useGetPackageDetail } from '../../services'

function usePackageDetailApiV2({ productCode: propProductCode, pageData, draftData }) {
  const location = useLocation()

  const apiConfigData = useMemo(() => pageData.package_detail_api, [pageData])

  const {
    state: { getPackageDetailData },
    request: getPackageDetailReq,
    loaders: { GET_PACKAGE_DETAIL_LOADER },
    setContextState,
  } = useGetPackageDetail()

  useEffect(() => {
    if (apiConfigData?.type !== PACKAGE_DETAIL_API.PACKAGE_DETAIL_API_V2) return
    if (!draftData) return

    // generate request body based on apiConfigData.request_body
    const payload = {}
    apiConfigData?.request_body?.forEach((key) => {
      _.set(payload, key, _.get(draftData, key))
    })

    getPackageDetailReq({
      packageCode: draftData?.package_data?.code,
      body: { ...payload },
    })
  }, [location, apiConfigData, draftData, getPackageDetailReq])

  useEffect(() => {
    return () => {
      // Reset data on leaving page
      setContextState({ getPackageDetailData: null })
    }
  }, [setContextState])

  return {
    getPackageDetailData,
    isPackageDetailLoading: GET_PACKAGE_DETAIL_LOADER,
  }
}

export default usePackageDetailApiV2
