import { clearLocalStorage } from '../../../../../helpers/localstorage'
import { loadDynamicScript } from '../../../../../helpers/loadDynamicScript'

export const loadSnapJs = () => {
  // Load snapjs for midtrans https://docs.midtrans.com/reference/snap-js
  clearLocalStorage()
  if (!window.snap) {
    loadDynamicScript(process.env.REACT_APP_PAYMENT_URL, 'snapjs', {
      'data-client-key': process.env.REACT_APP_PAYMENT_CLIENT_ID,
    })
  }
}

export const getPreValidateKeys = (policy, preValidateData) => {
  let keys = {}
  for (const key in preValidateData) {
    keys[key] = {}
    const keyItem = preValidateData[key] || []
    keyItem.forEach((propKeys) => {
      keys[key][propKeys] = policy[propKeys]
    })
  }

  return keys
}

export function calculatePayableAmount(policy) {
  if (policy?.use_instalment) {
    return (
      (policy?.upcoming_instalment.payable_amount || 0) -
      (policy?.upcoming_instalment.current_commission_used || 0) +
      (policy?.upcoming_instalment.stamp_duty || 0) +
      (policy?.upcoming_instalment.admin_fee || 0)
    )
  }
  return (
    (policy?.total_premium || 0) -
    (policy?.current_commission_used ? policy?.agent_commission || 0 : policy?.discount || 0)
  )
}
