export function getStepsData(config) {
  if (!config) return []
  return config?.data?.purchase_pages?.map((page, i) => ({
    index: String(i + 1),
    text: page.title,
  }))
}

export function getStepPrevActive(step) {
  if (!step) return {}
  const obj = {}
  for (let i = 1; i < Number(step); i++) {
    obj[i] = true
  }
  return obj // { 1: true, 2: true, 3: true, etc }
}

export function getPageData(config, step) {
  if (!config || !step) return {}
  const pageList = config?.data?.purchase_pages
  const pageIndex = pageList?.findIndex((_, i) => String(i + 1) === String(step))
  const pageStep = pageIndex + 1 // e.g. index = 0 -> step = 1
  return {
    pageData: pageList?.[pageIndex],
    pageIndex: pageIndex,
    pageStep: pageStep,
    prevPageData: pageList?.[pageIndex - 1],
    prevPageIndex: pageIndex - 1,
    prevPageStep: pageStep - 1,
    nextPageData: pageList?.[pageIndex + 1],
    nextPageIndex: pageIndex + 1,
    nextPageStep: pageStep + 1,
  }
}
