import _ from 'lodash'
import moment from 'moment'
import { dateAdd, dateSubtract, formatDate } from '../../../../../helpers/formatDate'
import { FIELD_TYPE } from '../../constants'

/**
 * Accepted @param {string} param
 * - 'D'
 * - 'D_{operation}_{num}_{unit}
 *   - operation: PLUS | MINUS
 *   - num: number
 *   - unit: DAY | WEEK | MONTH | YEAR
 * - 'FIELD_{{key}}_{operation}_{num}_{unit}
 *   - {key} field key for the reference value. please wrap the string in {} (e.g. `{start_date}`)
 * - date format (e.g. '01/01/2020')
 */
export const calculateDateValue = (value, field, draftData) => {
  if (!value) return null

  let dateValue
  switch (true) {
    case value === 'D':
      dateValue = new Date()
      break
    case value.startsWith('D_'): {
      const [, operation, num, unit] = value?.split('_')
      if (operation === 'PLUS') dateValue = dateAdd(new Date(), num, unit)
      if (operation === 'MINUS') dateValue = dateSubtract(new Date(), num, unit)
      break
    }
    case value.startsWith('FIELD_'): {
      const [, fieldKey, operation, num, unit] = value?.match(/\{[^}]+\}|[^_]+/g)
      const trimmedKey = _.trim(fieldKey, '{}')
      const referenceValue = _.get(draftData, trimmedKey)

      if (operation === 'PLUS') dateValue = dateAdd(referenceValue, num, unit)
      if (operation === 'MINUS') dateValue = dateSubtract(referenceValue, num, unit)
      break
    }
    default:
      dateValue = moment(value, field.params?.date_format_api)
      break
  }
  return formatDate(dateValue, field.params?.date_format_api)
}

export const preformatValue = (value, field, draftData) => {
  if (!value) return
  switch (field.type) {
    case FIELD_TYPE.DATE_SINGLE:
    case FIELD_TYPE.DATE_RANGE:
      const abc = calculateDateValue(value, field, draftData)
      return abc
    default:
      return value
  }
}
