import _ from 'lodash'
import { useCallback, useEffect } from 'react'
import { LANG_STRINGS } from '../../../../../lang'
import { Button } from '../../../../../components'
import ShowSnackbar from '../../../../../components/ShowNotification'
import { sharingViaWhatsApp } from '../../../../../helpers/sharingWA'
import XenditPayment from '../../../Payments/pages/XenditPayment'
import { shareCustomerPaymentLinkMessage } from '../../../Payments/pages/PaymentPage/container/helpers'
import { useGetPolicyApplicationDetail } from '../../services'
import { ButtonContainer, PaymentContainer, PolicySummary } from './index.style'

const POLICY_SUMMARY = [
  { label: LANG_STRINGS.policyHolder1, key: 'policy_detail.customer_data.policy_holder.name' },
  { label: LANG_STRINGS.typeInsurance, key: 'policy_detail.package.product.name' },
  { label: LANG_STRINGS.agentName, key: 'agent_info.name' },
  { label: LANG_STRINGS.packageTitle, key: 'policy_detail.package.name' },
]

function PaymentV1(props) {
  const { draftId: policyId, onPrevPage } = props

  const {
    state: { getPolicyApplicationDetailData: policyData },
    request: getPolicyApplicationDetailReq,
  } = useGetPolicyApplicationDetail()

  useEffect(() => {
    // On init, hit get policy API
    getPolicyApplicationDetailReq({ policyId, query: { show_agent: 1 } })
  }, [policyId, getPolicyApplicationDetailReq])

  const handleClickShare = useCallback(() => {
    if (!policyData?.invoice_receipt_url) {
      // Invoice is generated asynchronously. If invoice is not ready, retry API call
      ShowSnackbar.error({
        text: 'Invoice anda belum siap, silahkan coba lagi setelah 30 detik.',
      })
      getPolicyApplicationDetailReq({ policyId, query: { show_agent: 1 } })
      return
    }

    sharingViaWhatsApp({
      text: shareCustomerPaymentLinkMessage(policyData, policyData?.invoice_receipt_url),
    })
  }, [policyData, policyId, getPolicyApplicationDetailReq])

  return (
    <PaymentContainer>
      <PolicySummary>
        <div className="application-number">{policyData?.application_no}</div>
        <div className="policy-detail">
          {POLICY_SUMMARY.map((item, i) => (
            <div key={i}>
              <div className="label">{item.label}</div>
              <div className="data">{_.get(policyData, item.key, '-')}</div>
            </div>
          ))}
        </div>
      </PolicySummary>
      <XenditPayment policy={policyData} policyId={policyId} stepsHeader={true} paymentBy="agent" />
      <ButtonContainer>
        <Button variant="outlined" onClick={onPrevPage}>
          {LANG_STRINGS.return}
        </Button>
        <Button variant="filled" onClick={handleClickShare}>
          {LANG_STRINGS.share}
        </Button>
      </ButtonContainer>
    </PaymentContainer>
  )
}

export default PaymentV1
