import _ from 'lodash'
import { useCallback, useEffect, useMemo, useState } from 'react'
import Tabs from '../../../../../components/Tabs'
import { PACKAGE_CARDS, TAB_SECTION_TYPE, TEMPLATE_FOOTERS } from '../../constants'
import BasicPackageCardV1 from '../../components/packageCards/BasicPackageCardV1'
import TravelPackageCardV1 from '../../components/packageCards/TravelPackageCardV1'
import RichTextContent from '../../components/tabSections/RichTextContent'
import PremiumBreakdownFooterV1 from '../../components/footers/PremiumBreakdownFooterV1'
import usePackageDetailApiV2 from '../../hooks/packageApi/usePackageDetailApiV2'
import { mapTabData } from './helpers'
import { PackageDetailContainer, ActiveTabContainer } from './index.style'

function PackageDetailV1(props) {
  const { draftId, productCode, pageData, draftData, setIsLoadingOthers, onSaveDraft } = props

  const tabsData = useMemo(() => mapTabData(pageData), [pageData])
  const [activeTab, setActiveTab] = useState(tabsData[0])

  const { getPackageDetailData, isPackageDetailLoading } = usePackageDetailApiV2({
    productCode,
    pageData,
    draftData,
  })

  const packageData = useMemo(() => {
    if (!pageData?.package_detail_api?.response_key) return getPackageDetailData
    return _.get(getPackageDetailData, pageData?.package_detail_api?.response_key)
  }, [getPackageDetailData, pageData])

  useEffect(() => {
    setIsLoadingOthers(isPackageDetailLoading)
  }, [setIsLoadingOthers, isPackageDetailLoading])

  const handleClickNextPage = useCallback(() => {
    const _data = {
      ...draftData,
      package: packageData,
    }
    onSaveDraft(_data, true)
  }, [draftData, packageData, onSaveDraft])

  const renderPackageCard = useCallback(() => {
    switch (pageData?.package_display) {
      case PACKAGE_CARDS.BASIC_PACKAGE_CARD_V1:
        return <BasicPackageCardV1 variant="full" packageData={packageData} />
      case PACKAGE_CARDS.TRAVEL_PACKAGE_CARD_V1:
        return <TravelPackageCardV1 variant="full" packageData={packageData} />
      default:
        return <div />
    }
  }, [pageData, packageData])

  const renderSectionContent = useCallback(
    (section, idx) => {
      switch (section?.type) {
        case TAB_SECTION_TYPE.RICH_TEXT:
          return <RichTextContent key={idx} sectionData={section} packageData={packageData} />
        case TAB_SECTION_TYPE.ADDON_LIST:
        case TAB_SECTION_TYPE.HARDCOPY_CHECKBOX:
        default:
          return <div key={idx} />
      }
    },
    [packageData]
  )

  const renderFooter = useCallback(() => {
    switch (pageData?.footer_type) {
      case TEMPLATE_FOOTERS.PREMIUM_BREAKDOWN_V1:
        return (
          <PremiumBreakdownFooterV1
            productCode={productCode}
            draftId={draftId}
            pageData={pageData}
            draftData={draftData}
            packageData={packageData}
            onSaveDraft={onSaveDraft}
            onClickNextPage={handleClickNextPage}
          />
        )
      default:
        return <div />
    }
  }, [productCode, draftId, pageData, draftData, packageData, onSaveDraft, handleClickNextPage])

  return (
    <PackageDetailContainer>
      {renderPackageCard()}
      <Tabs
        data={tabsData}
        defaultTab={tabsData[0]}
        onClick={(tab) => setActiveTab(tab)}
        isSticky
      />
      {tabsData?.map((tab) => {
        if (activeTab.value !== tab?.value) return null
        const sections = pageData?.tabs?.[activeTab.value]?.sections
        return (
          <ActiveTabContainer key={tab?.value}>
            {sections.map((section, idx) => renderSectionContent(section, idx))}
          </ActiveTabContainer>
        )
      })}
      {renderFooter()}
    </PackageDetailContainer>
  )
}

export default PackageDetailV1
