import { forwardRef, useCallback, useState } from 'react'
import { ARROW_UP_BLACK, ARROW_DOWN_BLACK } from '../../../../../../images'
import { CustomText } from '../../../../../../components'
import DynamicForm from '../../../../../../components/DynamicForm'
import { AgentColorPallette } from '../../../../../../configs/colorPallete'
import { getFieldGroupFormData } from '../FieldGroup/helpers'
import { FieldGroupContainer } from './index.style'

const FieldGroupCollapsible = forwardRef(({ fieldGroup, draftData, onChange }, ref) => {
  const [isOpen, setIsOpen] = useState(!fieldGroup?.params?.default_collapse)

  const handleFormChange = useCallback((value) => onChange(value), [onChange])

  const formData = getFieldGroupFormData({
    fieldGroup,
    draftData,
    onChange: handleFormChange,
  })

  return (
    <FieldGroupContainer onClick={() => setIsOpen(!isOpen)}>
      <div className="collapse-header">
        <CustomText color={AgentColorPallette.darkCharcoal} size="12px" weight={700}>
          {fieldGroup.label}
        </CustomText>
        <img src={isOpen ? ARROW_UP_BLACK : ARROW_DOWN_BLACK} alt="⌃" />
      </div>

      {isOpen && (
        <div className="field-group-form" onClick={(e) => e.stopPropagation()}>
          <DynamicForm key={fieldGroup.key} ref={ref} form={formData} onChange={handleFormChange} />
        </div>
      )}
    </FieldGroupContainer>
  )
})

export default FieldGroupCollapsible
