import _ from 'lodash'
import { useEffect, useMemo } from 'react'
import { useLocation } from 'react-router'
import { PACKAGE_LIST_API } from '../../constants'
import { useGetPackageList } from '../../services'

function usePackageListApiV2({ productCode: propProductCode, pageData, draftData }) {
  const location = useLocation()

  const apiConfigData = useMemo(() => pageData.package_list_api, [pageData])

  const {
    state: { getPackageListData },
    request: getPackageListReq,
    loaders: { GET_PACKAGE_LIST_LOADER },
    setContextState,
  } = useGetPackageList()

  useEffect(() => {
    if (apiConfigData?.type !== PACKAGE_LIST_API.PACKAGE_LIST_API_V2) return
    if (!draftData) return

    // generate request body based on apiConfigData.request_body
    const payload = {}
    apiConfigData?.request_body?.forEach((key) => {
      _.set(payload, key, _.get(draftData, key))
    })

    getPackageListReq({
      productCode: propProductCode,
      body: { ...payload },
    })
  }, [location, propProductCode, apiConfigData, draftData, getPackageListReq])

  useEffect(() => {
    return () => {
      // Reset data on leaving page
      setContextState({ getPackageListData: null })
    }
  }, [setContextState])

  return {
    getPackageListData,
    isPackageListLoading: GET_PACKAGE_LIST_LOADER,
  }
}

export default usePackageListApiV2
