import get from 'lodash/get'

/**
 * Replace template placeholders in URL with actual values from data object
 * Supports placeholders in format: {key}, {nested.key.path}
 * @param {string} template - URL template with placeholders (e.g., 'https://api.com/{draft_id}/upload/{product.code}')
 * @param {Object} data - Data object containing values to replace
 * @returns {string} URL with placeholders replaced with actual values
 * @throws {Error} If template is not provided or if a placeholder value is not found
 *
 * @example
 * const url = replaceUrlTemplate(
 *   'https://api.com/{draft_id}/upload/{product.code}',
 *   { draft_id: '123', product: { code: 'travel' } }
 * )
 * // Returns: 'https://api.com/123/upload/travel'
 */
export const replaceUrlTemplate = (template, data) => {
  if (!template) {
    throw new Error('URL template is required')
  }

  if (!data || typeof data !== 'object') {
    throw new Error('Data object is required')
  }

  // Find all placeholders in format {key} or {nested.key.path}
  const placeholderRegex = /\{([^}]+)\}/g
  const missingKeys = []

  const replacedUrl = template.replace(placeholderRegex, (match, key) => {
    const value = get(data, key)

    if (value === undefined || value === null) {
      missingKeys.push(key)
      return match // Keep the placeholder if value not found
    }

    return String(value)
  })

  if (missingKeys.length > 0) {
    throw new Error(
      `Missing required values for URL template placeholders: ${missingKeys.join(', ')}`
    )
  }

  return replacedUrl
}
