import _ from 'lodash'
import { FIELD_TYPE, FIELD_TYPE_MAP } from '../../constants'
import FieldGroup from '../../components/formFields/FieldGroup'
import FieldGroupCollapsible from '../../components/formFields/FieldGroupCollapsible'
import { checkShowCondition, repeatField } from './helpers-common-params'
import { calculateDateValue, preformatValue } from './helpers-field'
import BulkUploadExcel from '../../components/formFields/BulkUploadExcel'

// re-export for easy access. Be careful not to loop imports!
export { checkShowCondition, repeatField, calculateDateValue, preformatValue }

export function flatMapSectionFields({ fields, draftData }) {
  return fields?.reduce((reduced, field) => {
    if (!!field?.params?.repeat_field) {
      // handle repeat_field common params
      reduced.push(...repeatField(field, draftData))
    } else {
      reduced.push(field)
    }
    return reduced
  }, [])
}

export function getFormData({ fields, draftData, onChange }) {
  const flatFields = flatMapSectionFields({ fields, draftData })
  return flatFields?.reduce((filtered, field) => {
    // handle show_on_condition common params
    const isShowField = checkShowCondition(field.params?.show_on_condition, draftData)
    if (!isShowField) return filtered

    // handle default_value check
    const prevValue = _.get(draftData, field.key)
    const defaultValue = preformatValue(field.params?.default_value, field, draftData)
    if (isShowField && _.isNil(prevValue) && !_.isNil(defaultValue)) {
      onChange({ [field.key]: defaultValue })
    }

    // handle static_value check
    const staticValue = preformatValue(field.params?.static_value, field, draftData)
    if (isShowField && prevValue !== staticValue && !_.isNil(staticValue)) {
      onChange({ [field.key]: staticValue })
    }

    // handle common props here
    const basicProps = {
      type: FIELD_TYPE_MAP[field.type],
      title: field.label,
      name: field.key,
      defaultValue: prevValue,
      required: field.params?.required,
      disabled: field.params?.disabled,
      hidden: !isShowField,
      regex_validation: field.params?.validation_regex?.regex,
      errormsg: field.params?.validation_regex?.error_message,
    }

    // handle field-specific props here
    switch (field.type) {
      case FIELD_TYPE.DATE_SINGLE:
      case FIELD_TYPE.DATE_RANGE:
        filtered.push({
          ...basicProps,
          data: {
            displayFormat: field.params?.date_format_display,
            dateFormat: field.params?.date_format_api,
            minDate: calculateDateValue(field.params?.min_date, field, draftData),
            maxDate: calculateDateValue(field.params?.max_date, field, draftData),
          },
        })
        break
      case FIELD_TYPE.RADIO_PILL:
        filtered.push({
          ...basicProps,
          data: {
            options: field.params?.options?.map((opt) => ({
              value: opt.value,
              label: opt.label,
              icon: opt.img,
              additional_value: opt.additional_value,
            })),
          },
        })
        break
      case FIELD_TYPE.NUMBER_STEPPER:
        filtered.push({
          ...basicProps,
          data: {
            min: field?.params?.min,
            max: field?.params?.max,
            decimal_place: field?.params?.decimal_place,
            increment_by: field?.params?.increment_by,
          },
        })
        break
      case FIELD_TYPE.INFORMATION_BOX:
        filtered.push({
          ...basicProps,
          data: {
            type: field?.params?.type,
            title: field?.params?.title,
            content: field?.params?.content,
          },
        })
        break
      case FIELD_TYPE.ACTION_BOX:
        filtered.push({
          ...basicProps,
          data: {
            type: field?.params?.type,
            title: field?.params?.title,
            content: field?.params?.content,
            actionType: field?.params?.action_type,
            actionLinkUrl: field?.params?.action_link_url,
            actionFormUpdateData: field?.params?.action_form_update_data,
          },
        })
        break
      case FIELD_TYPE.CHECKBOX:
        filtered.push({
          ...basicProps,
          required: field.params?.required,
          data: {
            description: field.params?.description,
          },
        })
        break
      case FIELD_TYPE.FIELD_GROUP:
      case FIELD_TYPE.FIELD_GROUP_COLLAPSIBLE:
        // no need to render here
        break
      case FIELD_TYPE.POPUP_API: {
        const apiConfig = field.params?.options_api_url
          ? {
              url: field.params.options_api_url,
              response_list_key: field.params.option_list_key,
              response_display_key: field.params?.option_display_key,
              response_value_key: field.params?.option_value_key,
              response_description_key: field.params?.option_description_key,
            }
          : null
        filtered.push({
          ...basicProps,
          data: {
            option_section_title: field.params?.option_section_title,
            apiConfig,
            is_multiple: field.params?.is_multiple,
            max_selected: field.params?.max_selected,
            is_searchable: field.params?.is_searchable,
          },
        })
        break
      }
      case FIELD_TYPE.POPUP_API_PINNED: {
        const apiConfig = field.params?.options_api_url
          ? {
              url: field.params.options_api_url,
              response_list_key: field.params.option_list_key,
              response_display_key: field.params?.option_display_key,
              response_value_key: field.params?.option_value_key,
              response_pinned_flag_key: field.params?.pinned_flag_key,
              response_description_key: field.params?.pinned_description_key,
            }
          : null
        filtered.push({
          ...basicProps,
          data: {
            option_section_title: field.params?.option_section_title,
            pinned_section_title: field.params?.pinned_section_title,
            apiConfig,
            is_multiple: field.params?.is_multiple,
            max_selected: field.params?.max_selected,
            is_searchable: field.params?.is_searchable,
          },
        })
        break
      }
      default:
        filtered.push(basicProps)
        break
    }
    return filtered
  }, [])
}

export function renderCustomFields({ formRefs, index, fields, draftData, onChange }, i) {
  const flatFields = flatMapSectionFields({ fields, draftData })
  return flatFields?.reduce((filtered, field) => {
    // handle show_on_condition common params
    const isShowField = checkShowCondition(field.params?.show_on_condition, draftData)
    if (!isShowField) return filtered

    const j = filtered?.length
    switch (field.type) {
      case FIELD_TYPE.FIELD_GROUP:
        filtered.push(
          <FieldGroup
            ref={(el) => (formRefs.current[`section-${i}-group-${j}`] = el)}
            key={field.key}
            fieldGroup={field}
            draftData={draftData}
            onChange={onChange}
          />
        )
        break
      case FIELD_TYPE.FIELD_GROUP_COLLAPSIBLE:
        filtered.push(
          <FieldGroupCollapsible
            ref={(el) => (formRefs.current[`section-${i}-group-${j}`] = el)}
            key={field.key}
            fieldGroup={field}
            draftData={draftData}
            onChange={onChange}
          />
        )
        break
      case FIELD_TYPE.BULK_UPLOAD_EXCEL_V1:
        filtered.push(
          <BulkUploadExcel
            key={field.key}
            fieldConfig={field}
            draftData={draftData}
            onChange={onChange}
          />
        )
        break
      default:
        break
    }
    return filtered
  }, [])
}
