import { useState } from 'react'
import { Button } from '../../../../../../components'
import { formatMoney } from '../../../../../../helpers/utility'
import { LANG_STRINGS } from '../../../../../../lang'
import DiscountBottomSheet from './DiscountBottomSheet'
import PremiumBreakdownBottomSheet from './PremiumBreakdownBottomSheet'
import ShareQuotationSlip from './ShareQuotationSlip'
import { FooterContainer, LeftSection, RightSection } from './index.style'

const FOOTER_STATE = {
  CLOSED: 'CLOSED',
  BREAKDOWN: 'BREAKDOWN',
  DISCOUNT: 'DISCOUNT',
  SHARE_QS: 'SHARE_QS',
}

function PremiumBreakdownFooterV1({
  productCode,
  draftId,
  pageData,
  draftData,
  packageData,
  onSaveDraft,
  onClickNextPage,
}) {
  const [state, setState] = useState(FOOTER_STATE.CLOSED)

  const isDiscountAllowed = pageData?.footer_params?.is_discount_allowed
  const isShareQsAllowed = pageData?.footer_params?.is_share_qs_allowed

  const handleAddDiscount = (amount) => {
    const _data = { ...draftData, discount: amount }
    onSaveDraft(_data, false)
    setState(FOOTER_STATE.BREAKDOWN)
  }

  const handleRemoveDiscount = () => {
    const _data = { ...draftData, discount: 0 }
    onSaveDraft(_data, false)
    setState(FOOTER_STATE.BREAKDOWN)
  }

  const isBreakdownOpen = state === FOOTER_STATE.BREAKDOWN || state === FOOTER_STATE.DISCOUNT

  return (
    <>
      <FooterContainer>
        <LeftSection
          onClick={() => setState(isBreakdownOpen ? FOOTER_STATE.CLOSED : FOOTER_STATE.BREAKDOWN)}
        >
          <div>Total Transaksi</div>
          <div>
            <span>{formatMoney(packageData?.premium_breakup?.grand_total, 0)}</span>
            <span>
              <i className={`fas ${isBreakdownOpen ? 'fa-angle-down' : 'fa-angle-up'}`}></i>
            </span>
          </div>
        </LeftSection>
        <RightSection>
          {isShareQsAllowed && (
            <Button variant="outlined" onClick={() => setState(FOOTER_STATE.SHARE_QS)}>
              {LANG_STRINGS.share}
            </Button>
          )}
          <Button variant="filled" onClick={onClickNextPage}>
            {LANG_STRINGS.buy}
          </Button>
        </RightSection>
      </FooterContainer>
      <PremiumBreakdownBottomSheet
        show={state === FOOTER_STATE.BREAKDOWN}
        packageData={packageData}
        onClose={() => setState(FOOTER_STATE.CLOSED)}
        isDiscountAllowed={isDiscountAllowed}
        onAddDiscount={() => setState(FOOTER_STATE.DISCOUNT)}
        onRemoveDiscount={handleRemoveDiscount}
      />
      <DiscountBottomSheet
        show={state === FOOTER_STATE.DISCOUNT}
        packageData={packageData}
        onClose={() => setState(FOOTER_STATE.BREAKDOWN)}
        onSave={handleAddDiscount}
      />
      <ShareQuotationSlip
        show={state === FOOTER_STATE.SHARE_QS}
        productCode={productCode}
        pageData={pageData}
        draftId={draftId}
        draftData={draftData}
        onClose={() => setState(FOOTER_STATE.CLOSED)}
      />
    </>
  )
}

export default PremiumBreakdownFooterV1
