import _ from 'lodash'
import { CONDITIONAL_OPERATOR, REPEAT_FIELD_TYPE } from '../../constants'

/** @returns {boolean} true if condition matches */
export function checkShowCondition(condition, draftData) {
  if (!condition) return true // if no condition is specified, always show
  switch (condition.operator) {
    case CONDITIONAL_OPERATOR.EQ:
      return _.get(draftData, condition.key) === condition.value
    case CONDITIONAL_OPERATOR.NOT_EQ:
      return _.get(draftData, condition.key) !== condition.value
    case CONDITIONAL_OPERATOR.GT:
      return _.get(draftData, condition.key) > condition.value
    case CONDITIONAL_OPERATOR.GTE:
      return _.get(draftData, condition.key) >= condition.value
    case CONDITIONAL_OPERATOR.LT:
      return _.get(draftData, condition.key) < condition.value
    case CONDITIONAL_OPERATOR.LTE:
      return _.get(draftData, condition.key) <= condition.value
    case CONDITIONAL_OPERATOR.AND:
      return condition.conditions?.every((cond) => checkShowCondition(cond, draftData)) ?? false
    case CONDITIONAL_OPERATOR.OR:
      return condition.conditions?.some((cond) => checkShowCondition(cond, draftData)) ?? false
    default:
      return false
  }
}

/** Repeats a field n amount of times */
export function repeatField(field, draftData) {
  const { repeat_field, ...restParams } = field?.params
  const returnData = []

  var repeatCount = 1
  switch (repeat_field?.type) {
    case REPEAT_FIELD_TYPE.STATIC:
      repeatCount = repeat_field?.static_count
      break
    case REPEAT_FIELD_TYPE.DYNAMIC:
      repeatCount = _.get(draftData, repeat_field?.dynamic_key)
      break
    default:
      break
  }

  for (let i = 0; i < repeatCount; i++) {
    const _field = _.cloneDeep(field)
    _field.key = `${field.key}[${i}]`
    _field.params = { ..._field.params } // Create new params object
    delete _field.params.repeat_field // Remove repeat_field

    if (repeat_field?.show_index_on_label) {
      _field.label = `${_field.label} ${i + 1}`
    }

    _field.params.fields = _field.params?.fields?.map((subfield, j) => {
      // for each sub-field
      const _subfield = _.cloneDeep(subfield)
      if (_subfield.params?.show_on_condition?.key?.includes(field.key)) {
        // update show_on_condition key
        const _replacedKey = _subfield.params.show_on_condition.key.replace(field.key, _field.key)
        _subfield.params.show_on_condition.key = _replacedKey
      }
      return _subfield
    })

    returnData.push(_field)
  }
  return returnData
}
