import { useMemo, useState } from 'react'
import { FIELD_TYPE } from '../../../constants'
import { checkShowCondition, flatMapSectionFields } from '../../../templates/FormV1/helpers'
import { FormFieldContainer, SectionTitle } from './index.style'
import { renderFieldGroup, renderFieldGroupCollapsible, renderFieldRow } from './helpers'

function FormFieldDisplay({ sectionData, draftData }) {
  const [openIndex, setOpenIndex] = useState(null)

  const sectionFields = useMemo(
    () => flatMapSectionFields({ fields: sectionData?.fields, draftData }),
    [sectionData, draftData]
  )

  return (
    <>
      <SectionTitle>{sectionData?.title}</SectionTitle>
      <FormFieldContainer>
        {sectionFields?.map((field, index) => {
          if (!checkShowCondition(field?.params?.show_on_condition, draftData)) {
            return null
          }
          switch (field?.type) {
            case FIELD_TYPE.FIELD_GROUP:
              return renderFieldGroup({ fieldGroup: field, draftData, index })
            case FIELD_TYPE.FIELD_GROUP_COLLAPSIBLE:
              return renderFieldGroupCollapsible({
                fieldGroup: field,
                draftData,
                index,
                openIndex,
                setOpenIndex,
              })
            default:
              return renderFieldRow({ field, draftData, index })
          }
        })}
      </FormFieldContainer>
    </>
  )
}

export default FormFieldDisplay
