import { useEffect, useState } from 'react'
import { useHistory } from 'react-router'
import {
  useErrorContextValue,
  useResetError,
} from '@pasarpolis/common-react-hooks'
import ShowSnackbar from '../../../../../components/ShowNotification/index'
import { LANG_STRINGS } from '../../../../../lang'
import { useValidateChassisNumber } from '../../../../../state/commonState/hooks/useCommonContext'
import {
  useCustomerPaying,
  useGeneratePaymentUrl,
} from '../../state/hooks/usePaymentState'
import { calculatePayableAmount, getPreValidateKeys } from './helpers'

function usePaymentByCustomer({
  policy,
  policyId,
  isPaymentByCustomer,
  setXenditUrl,
}) {
  const history = useHistory()

  const isCustomerCanPay = true // no identity check for customer payment
  const [isCustomerPayingReqSent, setIsCustomerPayingReqSent] = useState(null)
  const [isPassPreValidate, setIsPassPreValidate] = useState(null)

  const [{ validateChassisNoData = {} }, validateChassisNoRequest] =
    useValidateChassisNumber()
  const [{ customerPayingData }, customerPayingReq] = useCustomerPaying()
  const [{ getPaymentUrlData }, generatePaymentUrlReq] = useGeneratePaymentUrl()
  const { resetError } = useResetError()
  const [
    {
      validateChassisNoStatus,
      validateChassisNoErrorData,
      customerPayingStatus,
      customerPayingErrorData,
      getPaymentUrlStatus,
      getPaymentUrlErrorData,
    },
  ] = useErrorContextValue()

  useEffect(() => {
    if (!isPaymentByCustomer || !policy) return

    const params = policy?.product?.pre_validate_params
    if (policy?.policy_detail?.chasis_number && params) {
      // For MV case, pre-validate before allowing user can pay
      validateChassisNoRequest({
        body: {
          code: policy?.code,
          identifier_value: policy?.id?.replaceAll('-', ''),
          identifier: 'reference_id',
          pre_validate_data: getPreValidateKeys(policy?.policy_detail, params),
        },
      })
    } else {
      // For non-MV case, always pass pre-validate
      setIsPassPreValidate(true)
    }
  }, [isPaymentByCustomer, policy, validateChassisNoRequest, resetError])

  useEffect(() => {
    // Check response of chasis number pre-validate
    if (!isPaymentByCustomer || !validateChassisNoStatus) return

    if (validateChassisNoStatus !== 'success') {
      ShowSnackbar.error({ text: validateChassisNoErrorData?.message })
      resetError(['validateChassisNoStatus'])
      return
    }

    if (!!validateChassisNoData.success) {
      setIsPassPreValidate(true)
    } else {
      ShowSnackbar.error({ text: LANG_STRINGS.chassisNumberPolicyAlreadyExist })
      setIsPassPreValidate(false)
    }
    resetError(['validateChassisNoStatus'])
  }, [
    isPaymentByCustomer,
    validateChassisNoStatus,
    validateChassisNoData,
    validateChassisNoErrorData,
    resetError,
  ])

  useEffect(() => {
    // On init, automatically hit /customer-paying API
    if (!isPaymentByCustomer || isCustomerPayingReqSent === true) return

    const payableAmount = calculatePayableAmount(policy)
    if (policyId && payableAmount > 0 && isPassPreValidate) {
      customerPayingReq({
        policyId,
        body: {
          agent_paying: false,
          payable_amount: payableAmount,
          commission: { amount: 0, tax: 0 }, // this is legacy code, always hardcode to 0
          point: { amount: 0, point: 0, tax: 0 }, // this is legacy code, always hardcode to 0
        },
      })
      setIsCustomerPayingReqSent(true)
    }
  }, [
    isPaymentByCustomer,
    policyId,
    policy,
    customerPayingReq,
    isCustomerPayingReqSent,
    isPassPreValidate,
  ])

  useEffect(() => {
    // Once customer-paying is success, automatically hit /generate-token API
    if (!isPaymentByCustomer || !customerPayingStatus) return

    if (customerPayingStatus !== 'success') {
      ShowSnackbar.error({ text: customerPayingErrorData?.message })
      resetError(['customerPayingStatus'])
      return
    }

    // Generate payment url here
    const body = {
      payment_gateway: 'xendit',
      // payment_method: 'BANKING', // TODO: update or remove
      // bank_va: 'mandiri', // TODO: update or remove
      transaction_id: customerPayingData.transaction_id,
    }
    generatePaymentUrlReq({ body })
    resetError(['customerPayingStatus'])
  }, [
    history,
    isPaymentByCustomer,
    policyId,
    customerPayingStatus,
    customerPayingData,
    customerPayingErrorData,
    generatePaymentUrlReq,
    resetError,
  ])

  useEffect(() => {
    // Check generate token response
    if (!isPaymentByCustomer || !getPaymentUrlStatus) return

    if (getPaymentUrlStatus !== 'success') {
      if (
        getPaymentUrlErrorData?.error_code ===
        'PP-PAYMENT-NOT-ALLOWED-AT-THE-MOMENT'
      ) {
        ShowSnackbar.error({ text: getPaymentUrlErrorData?.message })
        resetError(['getPaymentUrlErrorData'])
        history.push(`/transactions/${policyId}/details`)
        return
      }
    }
    const paymentUrl = getPaymentUrlData?.payment_url

    if (paymentUrl) {
      setXenditUrl(paymentUrl)
      resetError(['getPaymentUrlStatus'])
      return
    }
  }, [
    history,
    isPaymentByCustomer,
    policyId,
    getPaymentUrlStatus,
    getPaymentUrlData,
    getPaymentUrlErrorData,
    setXenditUrl,
    resetError,
  ])

  return { isCustomerCanPay }
}

export default usePaymentByCustomer
