import _ from 'lodash'
import { useCallback, useEffect, useMemo } from 'react'
import { PACKAGE_CARDS } from '../../constants'
import BasicPackageCardV1 from '../../components/packageCards/BasicPackageCardV1'
import TravelPackageCardV1 from '../../components/packageCards/TravelPackageCardV1'
import usePackageListApiV2 from '../../hooks/packageApi/usePackageListApiV2'
import PackageNotFound from './PackageNotFound'
import { ListContainer } from './index.style'

function PackageSelectV1(props) {
  const {
    productCode,
    pageData,
    draftData,
    isPageLoading,
    setIsLoadingOthers,
    onPrevPage,
    onSaveDraft,
  } = props

  const { getPackageListData, isPackageListLoading } = usePackageListApiV2({
    productCode,
    pageData,
    draftData,
  })

  useEffect(() => {
    setIsLoadingOthers(isPackageListLoading)
  }, [setIsLoadingOthers, isPackageListLoading])

  const packageList = useMemo(() => {
    if (!pageData?.package_list_api?.response_key) return getPackageListData
    return _.get(getPackageListData, pageData?.package_list_api?.response_key)
  }, [getPackageListData, pageData])

  const handleSelectPkg = useCallback(
    (pkg) => {
      let _data = _.cloneDeep(draftData)
      _.set(_data, 'package.code', pkg.code)
      _.set(_data, 'package.provider', pkg.provider)
      _.set(_data, 'package.premium', pkg.premium)
      _.set(_data, 'package.premium_breakup', pkg.premium_breakup)
      _.set(_data, 'object_insured.area', pkg.object_insured.area)
      onSaveDraft(_data, true)
    },
    [draftData, onSaveDraft]
  )

  if (!isPageLoading && !isPackageListLoading && (!packageList || packageList?.length === 0)) {
    return <PackageNotFound onPrevPage={onPrevPage} />
  }

  return (
    <ListContainer>
      {packageList?.map((pkg, i) => {
        switch (pageData?.package_display) {
          case PACKAGE_CARDS.BASIC_PACKAGE_CARD_V1:
            return (
              <BasicPackageCardV1
                key={i}
                variant="card"
                packageData={pkg}
                onClick={handleSelectPkg}
              />
            )
          case PACKAGE_CARDS.TRAVEL_PACKAGE_CARD_V1:
            return (
              <TravelPackageCardV1
                key={i}
                variant="card"
                packageData={pkg}
                onClick={handleSelectPkg}
              />
            )
          default:
            return <div key={i} />
        }
      })}
    </ListContainer>
  )
}

export default PackageSelectV1
