import { useRef } from 'react'
import { StyleContainer } from './index.styles'
import { GREEN_CHECK_CIRCLE, UPLOAD_ICON } from '../../../../../../../images'
import LoaderSvg from '../../../../../../../components/CircularLoader/LoaderSvg'
import { UPLOAD_STATUS, ACCEPTED_FILE_TYPES } from '../constants'

const UploadArea = ({
  status,
  file,
  handleFileSelect,
  handleUploadAgain,
  handleDrop,
  handleDragOver,
}) => {
  const fileInputRef = useRef(null)

  const handleButtonClick = () => {
    fileInputRef.current.click()
  }
  const renderUploadArea = () => {
    switch (status) {
      case UPLOAD_STATUS.LOADING:
        return (
          <div className="upload-area">
            <div className="loading-icon">
              <LoaderSvg isLoader size="80px" />
            </div>
            <div className="file-name-text">{file?.name}</div>
            <div className="warning-text">
              Jangan menutup aplikasi Mitra dan pastikan koneksi internet Anda baik agar proses
              upload berhasil.
            </div>
            <button className="upload-button" onClick={handleUploadAgain}>
              Batal
            </button>
          </div>
        )
      case UPLOAD_STATUS.SUCCESS:
        return (
          <div className="upload-area">
            <div className="upload-icon">
              <img src={GREEN_CHECK_CIRCLE} alt="check-circle-green" />
            </div>
            <div className="success-text">
              <p className="success-title">Upload Berhasil</p>
              <p className="success-file">{file?.name}</p>
              <p className="success-count">Semua data berhasil diverifikasi.</p>
            </div>
            <button className="upload-button" onClick={handleButtonClick}>
              Upload Ulang
            </button>
          </div>
        )
      default:
        return (
          <div className="upload-area" onDrop={handleDrop} onDragOver={handleDragOver}>
            <div className="upload-icon">
              <img src={UPLOAD_ICON} alt="upload" />
            </div>
            <div className="upload-text">
              <span>Upload File</span>
            </div>
            <button className="upload-button" onClick={handleButtonClick}>
              Buka Folder
            </button>
          </div>
        )
    }
  }

  return (
    <StyleContainer>
      <div className="drag-drop-area">{renderUploadArea()}</div>
      <input
        type="file"
        ref={fileInputRef}
        style={{ display: 'none' }}
        accept={ACCEPTED_FILE_TYPES.join(',')}
        onChange={(e) => {
          handleFileSelect(e.target.files[0])
          e.target.value = ''
        }}
      />
    </StyleContainer>
  )
}

export default UploadArea
