import { useEffect, useState } from 'react'
import { Button } from '../../../../../../components'
import RadioV2 from '../../../../../../components/RadioV2'
import InputNumberV2 from '../../../../../../components/DynamicForm/components/InputNumberV2'
import BottomActionSheet from '../../../../../../components/BottomActionSheet'
import { AgentColorPallette } from '../../../../../../configs/colorPallete'
import { formatMoney } from '../../../../../../helpers/utility'
import { LANG_STRINGS } from '../../../../../../lang'
import {
  BottomSheetStyle,
  BottomSheetContent,
  ButtonContainer,
  CommissionSection,
  DiscountInputSection,
} from './DiscountBottomSheet.style'

const DISCOUNT_TYPE = {
  NOMINAL: 'NOMINAL',
  PERCENTAGE: 'PERCENTAGE',
}

function DiscountBottomSheet({ show, packageData, onClose, onSave }) {
  const [discountType, setDiscountType] = useState(DISCOUNT_TYPE.NOMINAL)
  const [discountPercentage, setDiscountPercentage] = useState(0)
  const [discountAmount, setDiscountAmount] = useState(packageData?.discount?.applied_amount || 0)
  const [error, setError] = useState(false)

  const [netCommission, setNetCommission] = useState(0)

  const maxDiscount = {
    amount: packageData?.discount?.max_discount_amount,
    percentage: packageData?.discount?.max_discount_rate,
  }

  useEffect(() => {
    // Update discount amount on packageData refetch
    setDiscountAmount(packageData?.discount?.applied_amount || 0)
  }, [packageData])

  useEffect(() => {
    const _netCommission = Math.round(packageData?.commission?.commission_amount) - discountAmount
    setNetCommission(_netCommission)
  }, [packageData, discountAmount])

  const handleInputChange = (type, value) => {
    let _amount, _percent
    if (type === DISCOUNT_TYPE.NOMINAL) {
      _amount = Number(value)
      _percent =
        Math.round((_amount / packageData?.premium_breakup?.base_premium?.amount) * 10000) / 100 // multiply by 100 to get 2 decimal place
    }
    if (type === DISCOUNT_TYPE.PERCENTAGE) {
      _percent = Number(value)
      _amount = Math.ceil((_percent * packageData?.premium_breakup?.base_premium?.amount) / 100)
    }

    if (_amount > maxDiscount.amount || _percent > maxDiscount.percentage) {
      setError(true)
      return
    }

    setError(false)
    setDiscountPercentage(_percent)
    setDiscountAmount(_amount)
  }

  const handleSave = () => {
    onSave(discountAmount)
    setDiscountAmount(0)
    setDiscountPercentage(0)
    setError(false)
  }

  return (
    <BottomSheetStyle>
      <BottomActionSheet
        show={show}
        showHeader
        title={LANG_STRINGS.addDiscount}
        backGroundColor={AgentColorPallette.primary}
        zIndex={101}
        onCloseSheet={onClose}
      >
        <BottomSheetContent>
          <DiscountInputSection>
            <div className="row discount-title">{LANG_STRINGS.enterDiscountNew}</div>
            <div className="input-container">
              <RadioV2
                name="discount_type"
                direction="horizontal"
                titleSize="10px"
                data={[
                  { value: DISCOUNT_TYPE.NOMINAL, name: LANG_STRINGS.nominalNew },
                  { value: DISCOUNT_TYPE.PERCENTAGE, name: LANG_STRINGS.percentageNew },
                ]}
                defaultValue={discountType}
                onChange={(value) => setDiscountType(value)}
              />
              {discountType === DISCOUNT_TYPE.NOMINAL && (
                <InputNumberV2
                  className="discount-input"
                  type="amount"
                  value={discountAmount}
                  onChange={({ value }) => handleInputChange(DISCOUNT_TYPE.NOMINAL, value)}
                  error={error}
                />
              )}
              {discountType === DISCOUNT_TYPE.PERCENTAGE && (
                <InputNumberV2
                  className="discount-input"
                  type="percentage"
                  value={discountPercentage}
                  onChange={({ value }) => handleInputChange(DISCOUNT_TYPE.PERCENTAGE, value)}
                  error={error}
                />
              )}
            </div>
            <div className={`row discount-footer ${error ? 'error' : ''}`}>
              Maks. {formatMoney(maxDiscount.amount, 0)}
            </div>
          </DiscountInputSection>

          <CommissionSection>
            <div className="row commission-title">{LANG_STRINGS.commissionCalculation}</div>
            <div className="row commission-item">
              <div>Komisi Anda di Transaksi ini</div>
              <div>{formatMoney(packageData?.commission?.commission_amount, 0)}</div>
            </div>
            <div className="row discount-item">
              <div>{LANG_STRINGS.discount}</div>
              <div>{formatMoney(-discountAmount, 0)}</div>
            </div>
            <div className="row commission-total">
              <div>Komisi Akhir (Sebelum dipotong PPh)</div>
              <div>{formatMoney(netCommission, 0)}</div>
            </div>
          </CommissionSection>
        </BottomSheetContent>

        <ButtonContainer>
          <Button variant="outlined" onClick={onClose}>
            {LANG_STRINGS.cancelSmall}
          </Button>
          <Button variant="filled" onClick={handleSave}>
            {LANG_STRINGS.saveNew}
          </Button>
        </ButtonContainer>
      </BottomActionSheet>
    </BottomSheetStyle>
  )
}

export default DiscountBottomSheet
