import _ from 'lodash'
import { Fragment } from 'react'
import { ARROW_DOWN_BLACK, ARROW_UP_BLACK } from '../../../../../../images'
import { formatMoney, formatNumber, formatPercentage } from '../../../../../../helpers/utility'
import { formatDate } from '../../../../../../helpers/formatDate'
import { FIELD_TYPE } from '../../../constants'
import { checkShowCondition } from '../../../templates/FormV1/helpers'

export function renderFieldData({ field, draftData }) {
  const _value = _.get(draftData, field?.key)
  switch (field?.type) {
    case FIELD_TYPE.TEXT:
      return _value || '-'
    case FIELD_TYPE.NUMBER_INTEGER:
    case FIELD_TYPE.NUMBER_DECIMAL:
      return formatNumber(_value) || '-'
    case FIELD_TYPE.NUMBER_PERCENTAGE:
      return formatPercentage(_value) || '-'
    case FIELD_TYPE.NUMBER_CURRENCY:
      return formatMoney(_value, 0) || '-'
    case FIELD_TYPE.DATE_SINGLE:
      return formatDate(_value, field?.params?.date_format_display) || '-'
    case FIELD_TYPE.RADIO_PILL:
      const opt = field?.params?.options?.find((opt) => opt.value === _value)
      return opt?.label || '-'
    case FIELD_TYPE.POPUP_API:
    case FIELD_TYPE.POPUP_API_PINNED:
      if (field?.params?.is_multiple === true) {
        return _value?.join(', ') || '-'
      } else {
        return _value || '-'
      }
    default:
      return _value || '-'
  }
}

export function renderFieldRow({ field, draftData, index }) {
  return (
    <div key={index} className="row">
      <div>{field?.label}</div>
      <div>{renderFieldData({ field, draftData })}</div>
    </div>
  )
}

export function renderFieldGroup({ fieldGroup, draftData, index }) {
  return (
    <Fragment key={index}>
      <div className="row row-group">
        <div>{fieldGroup?.label}</div>
      </div>
      {fieldGroup?.params?.fields?.map((field, j) => {
        if (!checkShowCondition(field?.params?.show_on_condition, draftData)) {
          return null
        }
        return (
          <div key={j} className="row">
            <div>{field?.label}</div>
            <div>
              {renderFieldData({
                field,
                draftData: _.get(draftData, fieldGroup?.key),
              })}
            </div>
          </div>
        )
      })}
    </Fragment>
  )
}

export function renderFieldGroupCollapsible({
  fieldGroup,
  draftData,
  index,
  openIndex,
  setOpenIndex,
}) {
  const isOpen = openIndex === index
  return (
    <Fragment key={index}>
      <div
        className="row row-group-collapsible"
        onClick={() => setOpenIndex(isOpen ? null : index)}
      >
        <div>{fieldGroup?.label}</div>
        <div>
          <img src={isOpen ? ARROW_UP_BLACK : ARROW_DOWN_BLACK} alt="⌃" />
        </div>
      </div>
      {isOpen &&
        fieldGroup?.params?.fields?.map((field, j) => {
          if (!checkShowCondition(field?.params?.show_on_condition, draftData)) {
            return null
          }
          return (
            <div key={j} className="row">
              <div>{field?.label}</div>
              <div>
                {renderFieldData({
                  field,
                  draftData: _.get(draftData, fieldGroup?.key),
                })}
              </div>
            </div>
          )
        })}
    </Fragment>
  )
}
