import { useCallback } from 'react'
import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useCommonContextValue } from '../../../contextProvider/CommonContext'
import {
  getCitiesAction,
  getInvoiceDetail,
  getSurveyForm,
  validateChassisNumber,
  getOfflineQuoteDetails,
} from '../actions'

export const useCommonServiceCall = (actionsCall = () => {}) => {
  const [commonState, dispatch] = useCommonContextValue()
  const [callApi] = useServiceRequest(dispatch)

  const request = useCallback(
    async (payload = {}) => {
      await callApi(
        actionsCall({
          ...payload,
        })
      )
    },
    [callApi, actionsCall]
  )

  return [commonState, request]
}

export const useGetCities = () => useCommonServiceCall(getCitiesAction)
export const useGetInvoiceDetail = () => useCommonServiceCall(getInvoiceDetail)

// validate chassis number
export const useValidateChassisNumber = () =>
  useCommonServiceCall(validateChassisNumber)
export const useGetSurveyForm = () => useCommonServiceCall(getSurveyForm)

// use get offline details
// use to get offline quote details api call
export const useGetOfflineQuoteDetail = () =>
  useCommonServiceCall(getOfflineQuoteDetails)

