import React, { useCallback, useEffect, useMemo, useState } from 'react'
import { useHistory, useRouteMatch } from 'react-router'
import { Container } from '../../../../components'
import PolicyStepsHeader from '../../../../components/PolicyStepsHeader'
import { CONFIG_TEMPLATE, NAV_ACTION } from '../constants'
import { useGetPurchaseFlowConfig } from '../services'
import useDraftApi from '../hooks/draftApi/useDraftApi'
import FormV1 from '../templates/FormV1'
import PackageSelectV1 from '../templates/PackageSelectV1'
import PackageDetailV1 from '../templates/PackageDetailV1'
import ConfirmationV1 from '../templates/ConfirmationV1'
import PaymentV1 from '../templates/PaymentV1'
import { getStepsData, getPageData, getStepPrevActive } from './helpers'
import { PageContainer } from './index.style'
import useEventTracker from '../../../../hooks/trackers'

function DynamicPurchaseFlowContainer() {
  const history = useHistory()
  const { params } = useRouteMatch()
  const { productCode, step, draftId } = params
  const { trackUserEvent } = useEventTracker()

  const [draftData, setDraftData] = useState(null)
  const [isLoadingOthers, setIsLoadingOthers] = useState(false)

  const {
    state: { getPurchaseFlowConfigData },
    request: getPurchaseFlowConfigReq,
    loaders: { GET_PURCHASE_FLOW_CONFIG_LOADER },
  } = useGetPurchaseFlowConfig()
  const configData = getPurchaseFlowConfigData?.data

  useEffect(() => {
    getPurchaseFlowConfigReq({ productCode })
  }, [getPurchaseFlowConfigReq, productCode])

  const { pageData, nextPageData, nextPageStep, prevPageStep, pageStep } = useMemo(
    () => getPageData(configData, step),
    [configData, step]
  )

  const {
    refetchGetDraft,
    isGetDraftLoading,
    saveToDraftApi,
    // debouncedSaveToDraft,
    isSaveLoading,
    completeDraftApi,
    isCompleteDraftLoading,
  } = useDraftApi({
    draftId: draftId,
    productCode: productCode,
    onGetDraftSuccess: (data) => setDraftData(data?.policy_details),
  })

  const isPageLoading =
    GET_PURCHASE_FLOW_CONFIG_LOADER ||
    isGetDraftLoading ||
    isSaveLoading ||
    isCompleteDraftLoading ||
    isLoadingOthers

  const navigateToPrevPage = useCallback(() => {
    if (prevPageStep >= 1) {
      // step starts at no 1
      history.push(`/purchase/${productCode}/${prevPageStep}/${draftId}`)
    } else {
      history.push('/dashboard')
    }
  }, [history, productCode, draftId, prevPageStep])

  const navigateToTransactionDetail = useCallback(() => {
    history.push(`/transactions/${draftId}/details`)
  }, [history, draftId])

  const navigateToNextPage = useCallback(
    (res) =>
      history.push(
        `/purchase/${productCode}/${nextPageStep}/${res?.policyId || res?.draftId || draftId}`
      ),
    [history, productCode, draftId, nextPageStep]
  )

  const navigateToHomepage = useCallback(() => {
    history.push('/dashboard')
  }, [history])

  const handleNavAction = useCallback(
    (action) => {
      switch (action) {
        case NAV_ACTION.PREV_PAGE:
          return navigateToPrevPage
        case NAV_ACTION.NEXT_PAGE:
          return navigateToNextPage
        case NAV_ACTION.HOMEPAGE:
          return navigateToHomepage
        case NAV_ACTION.TRANSACTION_DETAIL:
          return navigateToTransactionDetail
        default:
          return undefined
      }
    },
    [navigateToPrevPage, navigateToNextPage, navigateToHomepage, navigateToTransactionDetail]
  )

  const onBackClick = handleNavAction(pageData?.on_back_click)
  const onNextClick = handleNavAction(pageData?.on_next_click)
  const onClose = handleNavAction(pageData?.on_close)

  const handleSaveDraft = useCallback(
    (data, isNavigateToNextPage = false) => {
      if (pageData?.title) {
        trackUserEvent(`[Mitra] Complete Step ${pageStep} ${pageData.title}`, {
          draft_id: draftId || null,
          product_key: productCode,
        })
      }
      if (isNavigateToNextPage) {
        saveToDraftApi(data, nextPageData?.title, nextPageData?.title, navigateToNextPage)
      } else {
        saveToDraftApi(data, pageData?.title, pageData?.title, () => refetchGetDraft())
      }
    },
    [
      refetchGetDraft,
      saveToDraftApi,
      pageData,
      pageStep,
      nextPageData,
      navigateToNextPage,
      trackUserEvent,
      productCode,
      draftId,
    ]
  )

  const handleCompleteDraft = useCallback(
    (data) => {
      if (pageData?.title) {
        trackUserEvent(`[Mitra] Complete Step ${pageStep} ${pageData.title}`, {
          draft_id: draftId || null,
          product_key: productCode,
        })
      }
      const completeDraft = () => completeDraftApi(navigateToNextPage)
      saveToDraftApi(data, 'mv_quote_summary', 'mv_quote_summary', completeDraft)
    },
    [
      saveToDraftApi,
      completeDraftApi,
      navigateToNextPage,
      pageData,
      pageStep,
      trackUserEvent,
      productCode,
      draftId,
    ]
  )

  const renderPageByTemplate = useCallback(() => {
    switch (pageData?.template) {
      case CONFIG_TEMPLATE.FORM_V1:
        return (
          <FormV1
            draftId={draftId}
            pageData={pageData}
            draftData={draftData}
            onPrevPage={onBackClick}
            onNextPage={onNextClick}
            onSaveDraft={handleSaveDraft}
          />
        )
      case CONFIG_TEMPLATE.PACKAGE_SELECT_V1:
        return (
          <PackageSelectV1
            productCode={productCode}
            draftId={draftId}
            pageData={pageData}
            draftData={draftData}
            onPrevPage={onBackClick}
            onNextPage={onNextClick}
            onSaveDraft={handleSaveDraft}
            isPageLoading={isPageLoading}
            setIsLoadingOthers={setIsLoadingOthers}
          />
        )
      case CONFIG_TEMPLATE.PACKAGE_DETAIL_V1:
        return (
          <PackageDetailV1
            draftId={draftId}
            pageData={pageData}
            draftData={draftData}
            onPrevPage={onBackClick}
            onNextPage={onNextClick}
            onSaveDraft={handleSaveDraft}
            setIsLoadingOthers={setIsLoadingOthers}
          />
        )
      case CONFIG_TEMPLATE.CONFIRMATION_V1:
        return (
          <ConfirmationV1
            draftId={draftId}
            pageData={pageData}
            draftData={draftData}
            onPrevPage={onBackClick}
            onNextPage={onNextClick}
            onSaveDraft={handleSaveDraft}
            onCompleteDraft={handleCompleteDraft}
          />
        )
      case CONFIG_TEMPLATE.PAYMENT_V1:
        return (
          <PaymentV1
            draftId={draftId}
            pageData={pageData}
            draftData={draftData}
            onPrevPage={onBackClick}
            onNextPage={onNextClick}
            onSaveDraft={handleSaveDraft}
          />
        )
      default:
        return <div />
    }
  }, [
    productCode,
    draftId,
    pageData,
    draftData,
    isPageLoading,
    handleSaveDraft,
    handleCompleteDraft,
    onBackClick,
    onNextClick,
  ])

  return (
    <Container
      title={configData?.product_name}
      loader={isPageLoading}
      showInnerHeader
      hideBottomTabs
      showCloseIcon
      onClose={onClose}
      onBackClick={onBackClick}
    >
      <PolicyStepsHeader
        stepsData={getStepsData(configData)}
        activeCount={step}
        prevActive={getStepPrevActive(step)}
      />
      <PageContainer>{renderPageByTemplate()}</PageContainer>
    </Container>
  )
}

export default DynamicPurchaseFlowContainer
