import { useCallback } from 'react'
import { useHistory } from 'react-router'
import { Button } from '../../../../../components'
import { EDIT_ICON, HOME_ICON, PACKAGE_NOT_FOUND_IMG_SVG } from '../../../../../images'
import { NotFoundContainer, TextContainer, ActionContainer } from './PackageNotFound.style'

function PackageNotFound({ onPrevPage }) {
  const history = useHistory()

  const renderIconText = useCallback((icon, text, onClick) => {
    return (
      <div className="box-content" onClick={onClick}>
        <img className="action-icon" src={icon} alt={text} />
        <div className="action-text">{text}</div>
      </div>
    )
  }, [])

  return (
    <NotFoundContainer>
      <div>
        <img src={PACKAGE_NOT_FOUND_IMG_SVG} alt="Not-Found" width={200} height={200} />
        <TextContainer>
          <div className="title">Paket Tidak Tersedia</div>
          <div className="text">
            Maaf, saat ini tidak ada paket asuransi yang bisa dipilih secara online. Namun, Anda
            bisa melanjutkan pemesanan manual dengan bantuan tim kami.
          </div>
          <div className="text">
            Pembelian manual mungkin membutuhkan proses sedikit lebih lama, tapi kami pastikan Anda
            akan mendapatkan perlindungan terbaik dari kami!
          </div>
          <Button variant="filled" onClick={() => history.push('/offline/products')}>
            Menuju Pesanan Manual
          </Button>
        </TextContainer>
      </div>

      <ActionContainer>
        {renderIconText(EDIT_ICON, 'Ubah Pencarian', onPrevPage)}
        {renderIconText(HOME_ICON, 'Kembali Ke Beranda', () => history.push('/dashboard'))}
      </ActionContainer>
    </NotFoundContainer>
  )
}

export default PackageNotFound
