import _ from 'lodash'
import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { useHistory } from 'react-router'
import { Button } from '../../../../../../components'
import BottomActionSheet from '../../../../../../components/BottomActionSheet'
import DynamicForm from '../../../../../../components/DynamicForm'
import ShowSnackbar from '../../../../../../components/ShowNotification'
import { regex } from '../../../../../../constants/regex'
import { downloadFile } from '../../../../../../helpers/mitraUtils/mitra-utility'
import { sharingViaWhatsApp } from '../../../../../../helpers/sharingWA'
import {
  CLOSE_BLACK_ICON,
  DOWNLOAD_ICON_V3,
  HOME_ICON_V2,
  MV_QS_ICON,
  MV_SEND_ICON,
  WHATSAPP,
  YELLOW_SAND_TIME_LINE,
} from '../../../../../../images'
import { ERROR_LANG, LANG_STRINGS } from '../../../../../../lang/index'
import { useShareQuotationSlip } from '../../../services'
import {
  ShareQuotationFormStyle,
  ShareQuotationSuccessStyle,
  ActionContainer,
  ButtonContainer,
} from './ShareQuotationSlip.style'

const VIEW_STATE = {
  FORM: 'form',
  LOADING: 'loading',
  SUCCESS: 'success',
}

const shareQsFormData = (draftData) => [
  {
    type: 'inputV2',
    title: 'Nama Lengkap Pelanggan',
    name: 'name',
    defaultValue: draftData?.customer_data?.policy_holder?.name,
    required: true,
  },
  {
    type: 'inputPhoneNumber',
    title: 'Nomor Ponsel Pelanggan',
    name: 'phone_no',
    required: true,
    defaultValue: draftData?.customer_data?.policy_holder?.phone_no,
    validator: (value = '') => {
      if (!['+62', '62', '08'].some((pre) => value.startsWith(pre)))
        return ERROR_LANG.phoneNumberNotStartsWith62
      if (value.startsWith('+62') && value.length > 15) return ERROR_LANG.max15DigitAllowed
      if (value.length > 14) return ERROR_LANG.max14DigitAllowed
      if (!regex.phoneRegex.test(value)) return ERROR_LANG.phoneNumberError
    },
  },
  {
    type: 'inputV2',
    title: 'Email Pelanggan',
    name: 'email',
    defaultValue: draftData?.customer_data?.policy_holder?.email,
    required: true,
    validator: (value = '') => {
      if (!regex.emailRegex.test(value)) {
        return ERROR_LANG.emailRequiredError
      }
      return ''
    },
  },
]

function ShareQuotationSlip({ show, onClose, pageData, draftId, draftData }) {
  const formRef = useRef()
  const history = useHistory()

  const [viewState, setViewState] = useState(VIEW_STATE.FORM)
  const isBtnDisabled = viewState === VIEW_STATE.LOADING

  const {
    request: shareQuotationSlipReq,
    state: { shareQuotationSlipData },
    errors: { shareQuotationSlipStatus },
    resetError,
  } = useShareQuotationSlip()

  const pdfUrl = useMemo(
    () => shareQuotationSlipData?.quotation_pdf_url?.replaceAll(' ', '%20'),
    [shareQuotationSlipData]
  )

  useEffect(() => {
    if (shareQuotationSlipStatus !== 'success' && shareQuotationSlipStatus !== undefined) {
      ShowSnackbar.error({ text: ERROR_LANG.errorWhileUpdating })
      setViewState(VIEW_STATE.FORM)
    }
    resetError(['shareQuotationSlipStatus'])
  }, [shareQuotationSlipStatus, resetError])

  useEffect(() => {
    if (viewState === VIEW_STATE.LOADING && pdfUrl) {
      setViewState(VIEW_STATE.SUCCESS)
    }
  }, [pdfUrl, viewState])

  const handleSendQuote = () => {
    const validatedForm = formRef.current?.validateFormValues()
    if (!validatedForm) return

    const customerData = {}
    _.set(customerData, pageData?.footer_params?.share_qs_request_key?.name, validatedForm?.name)
    _.set(
      customerData,
      pageData?.footer_params?.share_qs_request_key?.phone_no,
      validatedForm?.phone_no
    )
    _.set(customerData, pageData?.footer_params?.share_qs_request_key?.email, validatedForm?.email)

    shareQuotationSlipReq({
      body: {
        draft_id: draftId,
        customer_data: customerData,
      },
    })
    setViewState(VIEW_STATE.LOADING)
  }

  const handleDownloadQS = async () => {
    try {
      await downloadFile(pdfUrl, 'Quotation.pdf')
    } catch (error) {
      ShowSnackbar.error({ text: ERROR_LANG.errorWhileUpdating })
    }
  }

  const handleShareToWhatsapp = () => {
    sharingViaWhatsApp({ text: pdfUrl })
  }

  const handleBackHome = () => {
    history.push({ pathname: '/dashboard' })
  }

  const handleClose = () => {
    if (isBtnDisabled) return
    setViewState(VIEW_STATE.FORM)
    if (onClose) onClose()
  }

  const renderIconText = useCallback(
    (icon, text, onClick) => {
      return (
        <div
          className={`box-content${isBtnDisabled ? ' is-disabled' : ''}`}
          onClick={isBtnDisabled ? undefined : onClick}
        >
          <img className="action-icon" src={icon} alt={text} />
          <div className="action-text">{text}</div>
        </div>
      )
    },
    [isBtnDisabled]
  )

  const renderContent = () => {
    switch (viewState) {
      case VIEW_STATE.FORM:
        return (
          <>
            <ShareQuotationFormStyle>
              <div className="close-cross">
                <img src={CLOSE_BLACK_ICON} alt="" onClick={handleClose} />
              </div>

              <div className="icon-container">
                <img src={MV_QS_ICON} alt="Send" />
              </div>
              <div className="title">Bagikan Penawaran</div>
              <div className="desc">
                Lengkapi data dibawah untuk mengirimkan penawaran asuransi.
              </div>

              <div className="form-container">
                <DynamicForm ref={formRef} form={shareQsFormData(draftData)} />
              </div>
            </ShareQuotationFormStyle>

            <ButtonContainer>
              <Button variant="filled" onClick={handleSendQuote}>
                {LANG_STRINGS.share}
              </Button>
            </ButtonContainer>
          </>
        )

      case VIEW_STATE.LOADING:
      case VIEW_STATE.SUCCESS:
        return (
          <>
            <ShareQuotationSuccessStyle>
              {viewState === VIEW_STATE.LOADING && (
                <>
                  <div className="icon-container">
                    <img src={YELLOW_SAND_TIME_LINE} alt="Processing" />
                  </div>
                  <div className="title">Dokumen Penawaran Diproses</div>
                  <div className="desc">
                    Silakan menunggu beberapa saat,
                    <br />
                    dokumen penawaran sedang kami proses.
                  </div>
                </>
              )}
              {viewState === VIEW_STATE.SUCCESS && (
                <>
                  <div className="icon-container">
                    <img src={MV_SEND_ICON} alt="Sent" />
                  </div>
                  <div className="title">Dokumen Penawaran Berhasil Dibuat</div>
                  <div className="desc">
                    Dokumen penawaran berhasil dibuat.
                    <br />
                    Silakan download atau bagikan dokumen penawaran.
                  </div>
                </>
              )}

              <ActionContainer>
                {renderIconText(DOWNLOAD_ICON_V3, 'Download Penawaran', handleDownloadQS)}
                {renderIconText(WHATSAPP, 'Bagikan via WhatsApp', handleShareToWhatsapp)}
                {renderIconText(HOME_ICON_V2, 'Kembali Ke Beranda', handleBackHome)}
              </ActionContainer>
            </ShareQuotationSuccessStyle>

            <ButtonContainer>
              <Button variant="filled" disabled={isBtnDisabled} onClick={handleClose}>
                {LANG_STRINGS.close}
              </Button>
            </ButtonContainer>
          </>
        )
      default:
        return null
    }
  }

  return (
    <BottomActionSheet show={show} onCloseSheet={handleClose} zIndex={101}>
      {renderContent()}
    </BottomActionSheet>
  )
}

export default ShareQuotationSlip
