import _ from 'lodash'
import { getFormData } from '../../../templates/FormV1/helpers'

export const mapFieldGroupFields = (fieldGroup) => {
  return fieldGroup?.params?.fields?.map((field) => {
    const clone = _.cloneDeep(field)
    clone.key = `${fieldGroup.key}.${field.key}`
    return clone
  })
}

export const getFieldGroupFormData = ({ fieldGroup, draftData, onChange }) => {
  return getFormData({
    fields: mapFieldGroupFields(fieldGroup),
    draftData: draftData,
    onChange: onChange,
  })
}
