import { useMemo, useCallback } from 'react'
import {
  resetError,
  useErrorContextValue,
  useLoaderContextValue,
} from '@pasarpolis/common-react-hooks'
import { useUploadBulkExcel } from '../../../../services'
import { downloadFile } from '../../../../../../../helpers/mitraUtils/mitra-utility'
import ShowSnackbar from '../../../../../../../components/ShowNotification'

export const useBulkUploadApi = () => {
  const [{ uploadBulkExcelErrorData = null }, dispatchError] = useErrorContextValue()
  const [{ UPLOAD_BULK_EXCEL_LOADER = false }] = useLoaderContextValue()
  const {
    state: { uploadBulkExcelData = {} },
    request: uploadBulkExcelRequest,
  } = useUploadBulkExcel()

  const isError = useMemo(() => Boolean(uploadBulkExcelErrorData), [uploadBulkExcelErrorData])
  const isSuccess = useMemo(() => Boolean(uploadBulkExcelData?.message), [uploadBulkExcelData])
  const isErrorPartial = useMemo(
    () =>
      Boolean(
        uploadBulkExcelErrorData &&
          uploadBulkExcelErrorData.detail != null &&
          typeof uploadBulkExcelErrorData.detail === 'object' &&
          Object.keys(uploadBulkExcelErrorData.detail).length > 0
      ),
    [uploadBulkExcelErrorData]
  )
  const errorMessage = useMemo(
    () => uploadBulkExcelErrorData?.error || '',
    [uploadBulkExcelErrorData]
  )

  const errorPartialCount = useMemo(
    () => ({
      failed: uploadBulkExcelErrorData?.detail?.count_failed || 0,
      success: uploadBulkExcelErrorData?.detail?.count_success || 0,
      total:
        (uploadBulkExcelErrorData?.detail?.count_failed || 0) +
        (uploadBulkExcelErrorData?.detail?.count_success || 0),
    }),
    [uploadBulkExcelErrorData]
  )

  const handleDownloadErrorData = useCallback(() => {
    // if not have file error, download the source file
    const url =
      uploadBulkExcelErrorData?.detail?.file_error_url ||
      uploadBulkExcelErrorData?.detail?.file_source_url ||
      ''
    const fileName = url.substring(url.lastIndexOf('/') + 1) || 'error.xlsx'
    if (url) {
      downloadFile(url, fileName)
    } else {
      ShowSnackbar.error({ message: 'File not found' })
    }
  }, [uploadBulkExcelErrorData])

  const handleResetError = useCallback(() => {
    dispatchError(
      resetError({
        uploadBulkExcelErrorData: undefined,
      })
    )
  }, [dispatchError])

  return {
    loading: Boolean(UPLOAD_BULK_EXCEL_LOADER),
    errorMessage,
    data: uploadBulkExcelData,
    isErrorPartial,
    isError,
    errorPartialCount,
    isSuccess,
    handleUploadBulkExcel: uploadBulkExcelRequest,
    handleDownloadErrorData,
    handleResetError,
  }
}
