import _ from 'lodash'
import { RichTextContainer, SectionTitle } from './index.style'

function RichTextContent({ sectionData, packageData }) {
  const data = _.get(packageData, sectionData?.params?.content_key)
  return (
    <>
      <SectionTitle>{sectionData?.title}</SectionTitle>
      <RichTextContainer>
        {data && <div dangerouslySetInnerHTML={{ __html: data?.content }} />}
      </RichTextContainer>
    </>
  )
}

export default RichTextContent
