import { useCallback, useState } from 'react'
import { CustomText } from '../../../../../../components'
import BottomActionSheet from '../../../../../../components/BottomActionSheet'
import { AgentColorPallette } from '../../../../../../configs/colorPallete'
import { formatMoney, formatPercentage } from '../../../../../../helpers/utility'
import { LANG_STRINGS } from '../../../../../../lang'
import {
  BottomSheetStyle,
  BottomSheetContent,
  PremiumBreakdownSection,
  PremiumTotal,
  FeesAndDiscountSection,
} from './PremiumBreakdownBottomSheet.style'
import { PLUS, RED_CROSS_CIRCLE } from '../../../../../../images'

function PremiumBreakdownBottomSheet({
  show,
  packageData,
  onClose,
  isDiscountAllowed,
  onAddDiscount,
  onRemoveDiscount,
}) {
  const [showBreakdownIndex, setShowBreakdownIndex] = useState(0)

  const isHaveDiscount = packageData?.discount?.applied_amount > 0

  const renderBreakdownTitle = useCallback(
    (section, i) => (
      <div className="row section-title" onClick={() => setShowBreakdownIndex(i)}>
        <div>{section?.label}</div>
        <span>
          <i className={`fas ${showBreakdownIndex === i ? 'fa-angle-up' : 'fa-angle-down'}`} />
        </span>
      </div>
    ),
    [showBreakdownIndex]
  )

  const renderBreakdownItem = useCallback(
    (section, i) => (
      <div className={`section-breakdown ${showBreakdownIndex === i ? 'show' : ''}`}>
        {section?.item?.map((item, j) => {
          const _tsi = formatMoney(item?.calculation?.sum_insured, 0)
          const _rate = formatPercentage(item?.calculation?.rate)
          return (
            <div key={j} className="row section-item">
              <div>
                <div>{item?.label}</div>
                {_tsi && _rate && (
                  <div className="item-calculation">
                    (<span className="tsi">{_tsi}</span>){` x ${_rate}`}
                  </div>
                )}
                {item?.metadata?.note && (
                  <div className="item-description">{item?.metadata?.note}</div>
                )}
              </div>
              <div>{formatMoney(item?.amount, 0)}</div>
            </div>
          )
        })}
      </div>
    ),
    [showBreakdownIndex]
  )

  const renderBreakdownSubtotal = useCallback(
    (section) => (
      <div className="row section-subtotal">
        <div>{LANG_STRINGS.subTotal}</div>
        <div>{formatMoney(section?.subtotal, 0)}</div>
      </div>
    ),
    []
  )

  return (
    <BottomSheetStyle>
      <BottomActionSheet
        show={show}
        showHeader
        title={LANG_STRINGS.transactionDetail}
        backGroundColor={AgentColorPallette.primary}
        zIndex={19}
        onCloseSheet={onClose}
      >
        <BottomSheetContent>
          <CustomText size="10px" weight={700} color={AgentColorPallette.ppBlue}>
            {LANG_STRINGS.customerPremium}
          </CustomText>

          {packageData?.premium_breakup?.section?.map((item, i) => (
            <PremiumBreakdownSection key={i}>
              {renderBreakdownTitle(item, i)}
              {renderBreakdownItem(item, i)}
              {renderBreakdownSubtotal(item, i)}
            </PremiumBreakdownSection>
          ))}

          <PremiumTotal className="row">
            <div>{LANG_STRINGS.newTotalBasicPremium}</div>
            <div>{formatMoney(packageData?.premium_breakup?.base_premium?.amount, 0)}</div>
          </PremiumTotal>

          <FeesAndDiscountSection>
            <div className="row fee-title">{LANG_STRINGS.others}</div>
            {packageData?.premium_breakup?.fee?.map((fee, i) => (
              <div key={i} className="row fee-item">
                <div>{fee?.label}</div>
                <div>{formatMoney(fee?.amount, 0)}</div>
              </div>
            ))}
            <div className={`row discount-item ${isHaveDiscount ? 'active' : 'inactive'}`}>
              <div>{LANG_STRINGS.discount}</div>
              <div>
                <div>{formatMoney(-packageData?.discount?.applied_amount, 0)}</div>
                {isDiscountAllowed && (
                  <>
                    {isHaveDiscount ? (
                      <img src={RED_CROSS_CIRCLE} alt="X" onClick={onRemoveDiscount} />
                    ) : (
                      <img src={PLUS} alt="+" onClick={onAddDiscount} />
                    )}
                  </>
                )}
              </div>
            </div>
          </FeesAndDiscountSection>

          <PremiumTotal className="row">
            <div>{LANG_STRINGS.totalTransaction}</div>
            <div>{formatMoney(packageData?.premium_breakup?.grand_total, 0)}</div>
          </PremiumTotal>
        </BottomSheetContent>
      </BottomActionSheet>
    </BottomSheetStyle>
  )
}

export default PremiumBreakdownBottomSheet
