import { useMemo } from 'react'
import { StyleContainer } from './index.styles'
import BottomActionSheet from '../../../../../../../components/BottomActionSheet'
import { AgentColorPallette } from '../../../../../../../configs/colorPallete'
import { ALERT_RED, INFORMATION_YELLOW } from '../../../../../../../images'
import { ERROR_TYPE } from '../constants'
import { Button } from '../../../../../../../components'

const ErrorModal = ({
  errorModalVisible,
  errorType,
  setErrorModalVisible,
  handleUploadAgain,
  handleDownloadError,
  errorPartialCount,
  errorMessage,
}) => {
  const contentMap = useMemo(
    () => ({
      [ERROR_TYPE.PARTIAL]: {
        iconSrc: INFORMATION_YELLOW,
        iconAlt: 'information',
        title: 'Upload Berhasil Sebagian',
        buttonText: 'Download Error Data',
        buttonHandler: handleDownloadError,
      },
      [ERROR_TYPE.FULL]: {
        iconSrc: ALERT_RED,
        iconAlt: 'alert',
        title: 'Terjadi Kesalahan',
        buttonText: 'Kembali',
        buttonHandler: handleUploadAgain,
      },
    }),
    [handleDownloadError, handleUploadAgain]
  )

  const { iconSrc, iconAlt, title, buttonText, buttonHandler } =
    contentMap[errorType] || contentMap[ERROR_TYPE.FULL]

  const descriptionMap = {
    [ERROR_TYPE.FULL]: () => (
      <>
        <p className="modal-desc full-error">{errorMessage}</p>
        <p className="modal-desc">
          Silakan upload ulang atau download template excel dari aplikasi Mitra.
        </p>
      </>
    ),
    [ERROR_TYPE.PARTIAL]: () => (
      <div className="modal-desc-partial">
        <p>
          Dari <span className="total-count">{errorPartialCount?.total || 0}</span> data diupload
          ditemukan:
        </p>
        <p>
          <span className="success-count">{errorPartialCount?.success || 0}</span> data valid,{' '}
          <span className="error-count">{errorPartialCount?.failed || 0}</span> data tidak valid.
          Silakan download file data yang error, kemudian perbaiki lalu upload ulang kembali.
        </p>
      </div>
    ),
  }

  const renderDescription = () => {
    const renderFn = descriptionMap[errorType] || descriptionMap[ERROR_TYPE.FULL]
    return renderFn()
  }

  return (
    <BottomActionSheet
      show={errorModalVisible}
      onCloseSheet={() => setErrorModalVisible(false)}
      showHeader={false}
    >
      <StyleContainer>
        <div className="modal-area">
          <div className="modal-top">
            <div className="modal-icon">
              <img src={iconSrc} alt={iconAlt} />
            </div>
            <div className="modal-text">
              <p className="modal-title">{title}</p>
              {renderDescription()}
            </div>
          </div>
          <div className="modal-buttons">
            <Button variant="filled" onClick={buttonHandler}>
              {buttonText}
            </Button>
          </div>
        </div>
        <div className="close-icon" onClick={() => setErrorModalVisible(false)}>
          <i
            className="fas fa-times"
            style={{ fontSize: 24, color: AgentColorPallette.darkCharcoal }}
          />
        </div>
      </StyleContainer>
    </BottomActionSheet>
  )
}

export default ErrorModal
