import _ from 'lodash'
import { useCallback, useEffect, useRef, useState } from 'react'
import { Button, CustomText } from '../../../../../components'
import DynamicForm from '../../../../../components/DynamicForm'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { LANG_STRINGS } from '../../../../../lang'
import { getFormData, renderCustomFields } from './helpers'
import { FormContainer, ButtonContainer } from './index.style'

function FormV1(props) {
  const { pageData, draftData, onSaveDraft } = props

  const formRefs = useRef({})

  const [currentDraftData, setCurrentDraftData] = useState(draftData || {})

  useEffect(() => {
    // Init currentDraftData after get draftData response
    if (draftData) setCurrentDraftData(draftData)
  }, [draftData])

  useEffect(() => {
    // Reset formRefs on page change
    formRefs.current = {}
  }, [pageData])

  const handleFormChange = useCallback(
    (value) => {
      const values = Object.entries(value)
      const _data = _.clone(currentDraftData)
      values.forEach(([key, val]) => _.set(_data, key, val))
      setCurrentDraftData(_data)
    },
    [currentDraftData]
  )

  const handleClickNext = useCallback(() => {
    // validate all DynamicForm data
    const validatedForms = Object.values(formRefs.current)
      ?.filter((ref) => ref !== null)
      ?.map((ref) => ref.validateFormValues())

    // if any value in validatedForms is nullish, then it's not valid
    const isValid = !validatedForms.some((v) => !v)
    if (!isValid) return

    onSaveDraft(currentDraftData, true)
  }, [currentDraftData, onSaveDraft])

  return (
    <FormContainer>
      {pageData?.sections?.map((section, i) => (
        <section key={section.title}>
          {section.title && (
            <CustomText color={AgentColorPallette.black} size="14px" weight={700} bottom="16px">
              {section.title}
            </CustomText>
          )}
          {section.description && (
            <CustomText color={AgentColorPallette.fontGrey} size="12px" weight={600} bottom="16px">
              {section.description}
            </CustomText>
          )}

          <DynamicForm
            ref={(el) => (formRefs.current[`section-${i}`] = el)}
            form={getFormData({
              fields: section?.fields,
              draftData: currentDraftData,
              onChange: handleFormChange,
            })}
            onChange={handleFormChange}
          />
          {renderCustomFields(
            {
              formRefs,
              fields: section?.fields,
              draftData: currentDraftData,
              onChange: handleFormChange,
            },
            i
          )}
        </section>
      ))}
      <ButtonContainer>
        <Button variant="filled" onClick={handleClickNext}>
          {LANG_STRINGS.nextSmall}
        </Button>
      </ButtonContainer>
    </FormContainer>
  )
}

export default FormV1
