import { formatMoney, formatNumber } from '../../../../../../helpers/utility'
import { CardContainer, TopSection, MiddleSection, BottomSection } from './index.style'

function BasicPackageCardV1({ variant, packageData, onClick }) {
  const handleClick = () => {
    if (onClick) onClick(packageData)
  }

  return (
    <CardContainer variant={variant} onClick={handleClick}>
      <TopSection>
        <img className="logo" src={packageData?.provider?.logo_url} alt="" />
        <div className="provider">{packageData?.provider?.name}</div>
        <div className="package">{packageData?.name}</div>
      </TopSection>
      <hr />
      <MiddleSection>
        <div>
          <div>Total Premi</div>
          <div>{formatMoney(packageData?.premium?.amount, 0)}</div>
        </div>
        <div>
          <div>Total Poin</div>
          <div>{formatNumber(packageData?.commission?.points_amount || 0, { suffix: 'P' })}</div>
        </div>
        <div>
          <div>Total Komisi</div>
          <div>{formatMoney(packageData?.commission?.commission_amount, 0)}</div>
        </div>
      </MiddleSection>
      {packageData?.content?.benefit_summary && (
        <BottomSection>
          <div
            dangerouslySetInnerHTML={{ __html: packageData?.content?.benefit_summary?.content }}
          />
        </BottomSection>
      )}
    </CardContainer>
  )
}

export default BasicPackageCardV1
