import { useCallback, useEffect, useRef } from 'react'
import { useLocation } from 'react-router'
import { cloneDeep, debounce } from 'lodash'
import { useResetError } from '@pasarpolis/common-react-hooks'
import {
  useCompletePolicyDraft,
  useCreatePolicyDraft,
  useGetPolicyDraft,
  useUpdatePolicyDraft,
} from '../../services'
import { getCreateApiPayload } from './helpers'
import ShowSnackbar from '../../../../../components/ShowNotification'

const SAVE_INTERVAL_MS = 5000 // 5s

const DEFAULT_ERROR_MSG = 'Terjadi kesalahan, silakan coba lagi'

const extractErrorMessage = (errorData) => {
  if (typeof errorData === 'string') return errorData
  if (errorData && typeof errorData === 'object' && typeof errorData.error === 'string') {
    return errorData.error
  }
  return DEFAULT_ERROR_MSG
}

const mapDraftBody = (data, section, subSection) => {
  return {
    section: section || '',
    sub_section: subSection || '',
    data: cloneDeep(data),
  }
}

function useDraftApi({
  draftId: propDraftId,
  productCode: propProductCode,
  onGetDraftSuccess,
  // onCompleteDraftSuccess,
}) {
  const location = useLocation()

  const draftIdRef = useRef(null)
  const createDraftDataRef = useRef(null)
  const saveDraftCallback = useRef(null)
  const completeDraftCallback = useRef(null)

  const {
    state: { getPolicyDraftData },
    request: getPolicyDraftReq,
    errors: { getPolicyDraftStatus },
    loaders: { GET_POLICY_DRAFT_LOADER },
  } = useGetPolicyDraft()
  const {
    state: { createPolicyDraftData },
    request: createPolicyDraftReq,
    errors: { createPolicyDraftStatus, createPolicyDraftErrorData },
    loaders: { CREATE_POLICY_DRAFT_LOADER },
  } = useCreatePolicyDraft()
  const {
    request: updatePolicyDraftReq,
    errors: { updatePolicyDraftStatus, updatePolicyDraftErrorData },
    loaders: { UPDATE_POLICY_DRAFT_LOADER },
  } = useUpdatePolicyDraft()
  const {
    state: { completePolicyDraftData },
    request: completePolicyDraftReq,
    errors: { completePolicyDraftStatus, completePolicyDraftErrorData },
    loaders: { COMPLETE_POLICY_DRAFT_LOADER },
  } = useCompletePolicyDraft()
  const { resetError } = useResetError()

  const isSaveLoading = CREATE_POLICY_DRAFT_LOADER || UPDATE_POLICY_DRAFT_LOADER
  const isCompleteDraftLoading = COMPLETE_POLICY_DRAFT_LOADER
  const isGetDraftLoading = GET_POLICY_DRAFT_LOADER

  // ===== GET draft ===== //

  const refetchGetDraft = useCallback(
    () => getPolicyDraftReq({ draftId: draftIdRef.current }),
    [getPolicyDraftReq]
  )

  useEffect(() => {
    if (propDraftId) {
      draftIdRef.current = propDraftId
    }

    // On page load: Get draft from API
    if (draftIdRef.current) {
      getPolicyDraftReq({ draftId: draftIdRef.current })
    }
  }, [location, propDraftId, getPolicyDraftReq])

  useEffect(() => {
    if (getPolicyDraftStatus === 'success' && getPolicyDraftData?.id) {
      onGetDraftSuccess(getPolicyDraftData)
      resetError(['getPolicyDraftStatus'])
    }
  }, [resetError, getPolicyDraftData, getPolicyDraftStatus, onGetDraftSuccess])

  // ===== POST create/update draft ===== //

  const saveToDraftApi = useCallback(
    (data, nextSection, nextSubSection, callback) => {
      // Store navigation preference in separate ref
      if (callback) {
        saveDraftCallback.current = callback
      }

      if (!draftIdRef.current) {
        const _data = getCreateApiPayload(propProductCode, data)
        createPolicyDraftReq({
          body: mapDraftBody(_data, nextSection, nextSubSection),
        })
        // Store data for re-update
        createDraftDataRef.current = { data: _data, nextSection, nextSubSection }
      } else {
        updatePolicyDraftReq({
          body: mapDraftBody(data, nextSection, nextSubSection),
          draftId: draftIdRef.current,
        })
      }
    },
    [propProductCode, createPolicyDraftReq, updatePolicyDraftReq]
  )

  const debouncedSaveToDraftApi = debounce(saveToDraftApi, SAVE_INTERVAL_MS)

  useEffect(() => {
    if (createPolicyDraftStatus === 'success') {
      resetError(['createPolicyDraftStatus'])

      // Save draft_id to local state
      draftIdRef.current = createPolicyDraftData.draft_id
      const { data, nextSection, nextSubSection } = createDraftDataRef.current
      // Automatically re-update to store draft_id in the draft data
      saveToDraftApi({ ...data, draft_id: draftIdRef.current }, nextSection, nextSubSection)
      createDraftDataRef.current = null

      if (saveDraftCallback.current) saveDraftCallback.current({ draftId: draftIdRef.current })
    }
  }, [resetError, createPolicyDraftStatus, createPolicyDraftData, saveToDraftApi])

  useEffect(() => {
    // Handle the logic for 2 case: save on click next & on auto save
    if (updatePolicyDraftStatus === 'success') {
      resetError(['updatePolicyDraftStatus'])

      if (saveDraftCallback.current) saveDraftCallback.current({ draftId: draftIdRef.current })
    }
  }, [resetError, updatePolicyDraftStatus])

  useEffect(() => {
    if (createPolicyDraftErrorData) {
      ShowSnackbar.error({ text: extractErrorMessage(createPolicyDraftErrorData) })
      resetError(['createPolicyDraftStatus', 'createPolicyDraftErrorData'])
    }
  }, [resetError, createPolicyDraftErrorData])

  useEffect(() => {
    if (updatePolicyDraftErrorData) {
      ShowSnackbar.error({ text: extractErrorMessage(updatePolicyDraftErrorData) })
      resetError(['updatePolicyDraftStatus', 'updatePolicyDraftErrorData'])
    }
  }, [resetError, updatePolicyDraftErrorData])

  useEffect(() => {
    if (completePolicyDraftErrorData) {
      ShowSnackbar.error({ text: extractErrorMessage(completePolicyDraftErrorData) })
      resetError(['completePolicyDraftStatus', 'completePolicyDraftErrorData'])
    }
  }, [resetError, completePolicyDraftErrorData])

  // ===== POST complete draft ===== //

  const completeDraftApi = useCallback(
    (callback) => {
      // Store navigation preference in separate ref
      if (callback) {
        completeDraftCallback.current = callback
      }

      completePolicyDraftReq({
        body: {},
        draftId: draftIdRef.current,
      })
    },
    [completePolicyDraftReq]
  )

  useEffect(() => {
    if (completePolicyDraftStatus === 'success' && completePolicyDraftData?.id) {
      resetError(['completePolicyDraftStatus'])

      if (completeDraftCallback.current)
        completeDraftCallback.current({ policyId: completePolicyDraftData?.id })
    }
  }, [resetError, completePolicyDraftStatus, completePolicyDraftData])

  return {
    refetchGetDraft,
    isGetDraftLoading,
    saveToDraftApi,
    debouncedSaveToDraftApi,
    isSaveLoading,
    completeDraftApi,
    isCompleteDraftLoading,
  }
}

export default useDraftApi
